/**
 * RoleRouter.tsx — Role-based portal routing with URL prefix enforcement
 *
 * Source of truth: docs/INSTRUCTION_MANUAL.md §2.3
 *
 * Routes the authenticated user to the correct portal
 * based on their role:
 *
 *   grand_master / master / admin / admin_officer / nzscv_monitor
 *     → Admin shell  (/admin/*)
 *
 *   officer
 *     → Officer shell (/officer/*)
 *
 *   scan_operator (or officer with standalone mode)
 *     → Scan shell   (/scan)
 *
 *   client_admin / client_officer / client_viewer
 *     → Client shell  (/client/*)
 *
 * Admin officers see a portal selection screen.
 * URL prefix is enforced: if the URL doesn't match the role, <Navigate> redirects.
 */

import React, { useState } from 'react';
import { Routes, Route, Navigate, useLocation, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { AdminShell } from '../shells/AdminShell';
import { OfficerShell } from '../shells/OfficerShell';
import { ClientShell } from '../shells/ClientShell';
import { ScanShell } from '../shells/ScanShell';
import { LoadingScreen } from '../components/LoadingScreen';

const PORTAL_CHOICE_KEY = 'fcm.admin_officer.portal';
type PortalChoice = 'admin' | 'field';

export function RoleRouter() {
  const { profile, loading } = useAuth();
  const location = useLocation();
  const navigate = useNavigate();
  const [portalChoice, setPortalChoice] = useState<PortalChoice | null>(
    () => (sessionStorage.getItem(PORTAL_CHOICE_KEY) as PortalChoice | null),
  );

  if (loading) return <LoadingScreen />;

  if (!profile) return null;

  const { role } = profile;

  function choosePortal(choice: PortalChoice | null) {
    if (choice) sessionStorage.setItem(PORTAL_CHOICE_KEY, choice);
    else sessionStorage.removeItem(PORTAL_CHOICE_KEY);
    setPortalChoice(choice);
    // Navigate to the chosen portal prefix
    if (choice === 'admin') navigate('/admin', { replace: true });
    else if (choice === 'field') navigate('/officer', { replace: true });
  }

  // Determine the expected URL prefix for this role.
  let expectedPrefix: string;

  if (role === 'admin_officer') {
    if (!portalChoice) {
      // Show portal selector — no prefix enforcement yet
      return (
        <PortalSelector
          officerName={profile.displayName ?? 'Officer'}
          onChoose={choosePortal}
        />
      );
    }
    expectedPrefix = portalChoice === 'admin' ? '/admin' : '/officer';
  } else if (role === 'scan_operator') {
    // Scan operators always go to the lightweight /scan shell — no roster,
    // dispatch, welfare, or full dashboard. (#150 slice 2)
    expectedPrefix = '/scan';
  } else if (
    role === 'grand_master' ||
    role === 'master' ||
    role === 'admin' ||
    role === 'nzscv_monitor'
  ) {
    expectedPrefix = '/admin';
  } else if (role === 'officer') {
    expectedPrefix = '/officer';
  } else if (
    role === 'client_admin' ||
    role === 'client_officer' ||
    role === 'client_viewer'
  ) {
    expectedPrefix = '/client';
  } else {
    return (
      <div style={{ padding: 32, color: 'var(--color-text-primary)' }}>
        Unknown role: {role}. Contact your administrator.
      </div>
    );
  }

  // Redirect if the URL prefix doesn't match the role.
  const path = location.pathname;
  if (!path.startsWith(expectedPrefix)) {
    return <Navigate to={expectedPrefix} replace />;
  }

  // Render the correct shell under its prefix.
  if (expectedPrefix === '/admin') {
    return (
      <Routes>
        <Route path="/admin" element={<AdminShell />} />
        <Route path="/admin/:page" element={<AdminShell />} />
        <Route path="*" element={<Navigate to="/admin" replace />} />
      </Routes>
    );
  }

  if (expectedPrefix === '/officer') {
    return (
      <Routes>
        <Route path="/officer" element={<OfficerShell />} />
        <Route path="/officer/:module" element={<OfficerShell />} />
        <Route path="*" element={<Navigate to="/officer" replace />} />
      </Routes>
    );
  }

  if (expectedPrefix === '/scan') {
    return (
      <Routes>
        <Route path="/scan" element={<ScanShell />} />
        <Route path="*" element={<Navigate to="/scan" replace />} />
      </Routes>
    );
  }

  if (expectedPrefix === '/client') {
    return (
      <Routes>
        <Route path="/client" element={<ClientShell />} />
        <Route path="/client/*" element={<ClientShell />} />
        <Route path="*" element={<Navigate to="/client" replace />} />
      </Routes>
    );
  }

  return null;
}

/** Portal chooser shown to admin_officer at login. */
function PortalSelector({ officerName, onChoose }: {
  officerName: string;
  onChoose: (choice: 'admin' | 'field') => void;
}) {
  return (
    <div style={ps.page}>
      <div style={ps.card}>
        <div style={ps.title}>Welcome, {officerName.split(' ')[0]}</div>
        <div style={ps.hint}>You have dual access. Choose how you want to work right now.</div>
        <div style={ps.grid}>
          <button type="button" style={ps.choice} onClick={() => onChoose('admin')} aria-label="Enter Admin portal">
            <span style={{ fontSize: 40 }}>🖥️</span>
            <span style={ps.choiceLabel}>Admin Portal</span>
            <span style={ps.choiceSub}>Manage operations, staff, compliance</span>
          </button>
          <button type="button" style={ps.choice} onClick={() => onChoose('field')} aria-label="Enter Field portal">
            <span style={{ fontSize: 40 }}>🚶</span>
            <span style={ps.choiceLabel}>Field Portal</span>
            <span style={ps.choiceSub}>Patrol, scan, welfare check-in, PTT</span>
          </button>
        </div>
        <div style={ps.note}>You can switch portals by signing out and back in.</div>
      </div>
    </div>
  );
}

const ps: Record<string, React.CSSProperties> = {
  page:        { minHeight: '100dvh', background: 'var(--color-bg-base, #121212)', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 16, fontFamily: 'var(--font-family, Inter, system-ui, sans-serif)' },
  card:        { background: '#1E1E1E', border: '1px solid rgba(158,158,158,0.15)', borderRadius: 12, padding: '32px 24px', width: '100%', maxWidth: 480, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 8, boxShadow: '0 8px 32px rgba(0,0,0,0.6)' },
  title:       { fontSize: 22, fontWeight: 700, color: '#FFFFFF', textAlign: 'center' },
  hint:        { fontSize: 14, color: '#9E9E9E', textAlign: 'center', lineHeight: 1.5, marginBottom: 12 },
  grid:        { display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12, width: '100%' },
  choice:      { background: '#2A2A2A', border: '1px solid rgba(158,158,158,0.2)', borderRadius: 12, cursor: 'pointer', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 8, minHeight: 150, padding: '16px 10px', fontFamily: 'inherit' },
  choiceLabel: { fontSize: 16, fontWeight: 700, color: '#FFFFFF', textAlign: 'center' },
  choiceSub:   { fontSize: 12, color: '#9E9E9E', textAlign: 'center', lineHeight: 1.4 },
  note:        { fontSize: 12, color: '#757575', textAlign: 'center', marginTop: 12 },
};
